SELECT DATE_TRUNC('WEEK', start_date) AS week_start, plan, DATE_TRUNC('QUARTER', end_date) AS quarter_start, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS row_count, COUNT(*) FILTER (WHERE plan = 'enterprise') AS enterprise_rows, COUNT(CASE WHEN status = 'ACTIVE' THEN 1 END) AS active_count, ROUND(SUM(monthly_fee) / NULLIF(COUNT(CASE WHEN status = 'CANCELLED' THEN 1 END), 0), 2) AS monthly_fee_per_cancelled FROM subscriptions GROUP BY DATE_TRUNC('WEEK', start_date), plan, DATE_TRUNC('QUARTER', end_date) ORDER BY monthly_fee_per_cancelled DESC NULLS LAST
